scores = {"fun": 1, "great": 1, "love": 1, "boring": -1, "tired": -1, "lost": -1}
message = "the trip was fun and great"
score = 0
for word in message.split():
    score = score + scores.get(word, 0)
print("happy" if score > 0 else "not happy")

